  <style>
    :root {
      color-scheme: dark;
      --bg: #090b10;
      --panel: #111722;
      --panel-soft: #171f2d;
      --text: #f4f7fb;
      --muted: #a9b3c7;
      --danger: #ff4d67;
      --danger-dark: #c93049;
      --border: rgba(255, 255, 255, 0.1);
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 32px;
      background:
        radial-gradient(circle at top left, rgba(84, 101, 255, 0.18), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(255, 77, 103, 0.12), transparent 30rem),
        var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    .page {
      width: min(100%, 860px);
    }

    .preview-card {
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: 28px;
      background: linear-gradient(145deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03));
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .image-wrap {
      position: relative;
      padding: 18px;
      background: rgba(255, 255, 255, 0.035);
    }

    .image-wrap img {
      display: block;
      width: 100%;
      aspect-ratio: 16 / 10;
      object-fit: cover;
      border-radius: 20px;
      box-shadow: inset 0 0 0 1px var(--border);
    }

    .caption {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      padding: 24px;
    }

    h1,
    p {
      margin: 0;
    }

    h1 {
      font-size: clamp(1.5rem, 2vw, 2.25rem);
      letter-spacing: -0.04em;
    }

    .caption p {
      margin-top: 8px;
      color: var(--muted);
    }

    button {
      border: 0;
      border-radius: 999px;
      color: inherit;
      font: inherit;
      cursor: pointer;
      transition: transform 180ms ease, background 180ms ease, border-color 180ms ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(255, 255, 255, 0.55);
      outline-offset: 3px;
    }

    .trigger {
      flex: 0 0 auto;
      padding: 13px 20px;
      background: rgba(255, 77, 103, 0.12);
      border: 1px solid rgba(255, 77, 103, 0.34);
      color: #ffd8de;
      font-weight: 700;
    }

    .trigger:hover {
      background: rgba(255, 77, 103, 0.2);
    }

    .modal-overlay {
      position: fixed;
      inset: 0;
      display: none;
      place-items: center;
      padding: 24px;
      background: rgba(3, 5, 10, 0.76);
      backdrop-filter: blur(10px);
      z-index: 10;
    }

    .modal-overlay.is-open {
      display: grid;
    }

    .modal {
      width: min(100%, 460px);
      border: 1px solid var(--border);
      border-radius: 24px;
      background: linear-gradient(180deg, var(--panel-soft), var(--panel));
      box-shadow: var(--shadow);
      padding: 28px;
      transform: scale(0.96) translateY(10px);
      opacity: 0;
      transition: transform 180ms ease, opacity 180ms ease;
    }

    .modal-overlay.is-open .modal {
      transform: scale(1) translateY(0);
      opacity: 1;
