      display: grid;
      place-items: center;
      margin-bottom: 18px;
      border-radius: 18px;
      background: rgba(255, 77, 103, 0.14);
      color: var(--danger);
      font-size: 1.5rem;
      font-weight: 900;
    }

    .modal h2 {
      margin: 0 0 10px;
      font-size: 1.55rem;
      letter-spacing: -0.03em;
    }

    .modal p {
      color: var(--muted);
      line-height: 1.6;
    }

    .modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 28px;
    }

    .button-secondary,
    .button-danger {
      padding: 12px 18px;
      font-weight: 700;
    }

    .button-secondary {
      background: rgba(255, 255, 255, 0.08);
      border: 1px solid var(--border);
      color: var(--text);
    }

    .button-secondary:hover {
      background: rgba(255, 255, 255, 0.13);
    }

    .button-danger {
      background: linear-gradient(180deg, var(--danger), var(--danger-dark));
      color: #fff;
      box-shadow: 0 12px 28px rgba(255, 77, 103, 0.25);
    }

    .button-danger:hover {
      background: linear-gradient(180deg, #ff6379, var(--danger-dark));
    }

    @media (max-width: 640px) {
      body {
        padding: 18px;
      }

      .caption,
      .modal-actions {
        align-items: stretch;
        flex-direction: column;
      }

      .trigger,
      .modal-actions button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="preview-card" aria-labelledby="image-title">
      <div class="image-wrap">
        <img
          src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80"
          alt="A cabin beside a lake under a vivid sunset sky"
        >
      </div>
      <div class="caption">
        <div>
          <h1 id="image-title">Sunset Cabin</h1>
          <p>Saved in your landscape library.</p>
        </div>
        <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
          Delete image
        </button>
      </div>
    </section>
  </main>

  <div class="modal-overlay" id="modal-overlay" hidden>
    <section
      class="modal"
      id="delete-dialog"
      role="dialog"
      aria-modal="true"
      aria-labelledby="dialog-title"
      aria-describedby="dialog-description"
      tabindex="-1"
    >
      <div class="modal-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">
        This will remove "Sunset Cabin" from your library. This action cannot be undone.
      </p>
      <div class="modal-actions">
        <button class="button-secondary" type="button" data-close-modal>Cancel</button>
        <button class="button-danger" type="button" data-confirm-delete>Delete permanently</button>
      </div>
    </section>
  </div>

  <script>
    const trigger = document.querySelector('.trigger');
    const overlay = document.querySelector('#modal-overlay');
    const dialog = document.querySelector('#delete-dialog');
    const closeButtons = document.querySelectorAll('[data-close-modal]');
    const confirmButton = document.querySelector('[data-confirm-delete]');

    function openModal() {
      overlay.hidden = false;
      overlay.classList.add('is-open');
      trigger.setAttribute('aria-expanded', 'true');
      dialog.focus();
    }

    function closeModal() {
      overlay.classList.remove('is-open');
      overlay.hidden = true;
      trigger.setAttribute('aria-expanded', 'false');
      trigger.focus();
    }

    trigger.setAttribute('aria-expanded', 'false');
    trigger.addEventListener('click', openModal);

    closeButtons.forEach((button) => {
      button.addEventListener('click', closeModal);
    });

    overlay.addEventListener('click', (event) => {
      if (event.target === overlay) {
        closeModal();
      }
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && !overlay.hidden) {
        closeModal();
      }
    });

    confirmButton.addEventListener('click', () => {
      closeModal();
    });
  </script>
</body>
</html>
